existing('t4',10,1,20)
add('pt16',10,'构建可配置的两层 MLP',2,'实现',
 'Sequential 把上一层的输出传给下一层。分类模型最后通常输出原始logits，交叉熵内部会完成稳定归一化。提前softmax会改变损失的输入含义。',
 'm=torch.nn.Sequential(torch.nn.Linear(3,4),torch.nn.ReLU(),torch.nn.Linear(4,2))\nprint(list(m(torch.ones(5,3)).shape))',
 ['返回 Linear→ReLU→Linear 的nn.Module，所有维度来自函数参数。','最后输出logits，不加softmax。Linear默认有bias。','检查参数注册与batch=1的形状；两层参数数应为 in_dim*hidden+hidden+hidden*classes+classes。'],
 '定义 make_mlp(in_dim,hidden,classes)，返回上述含bias的两层ReLU模型。','def make_mlp(in_dim, hidden, classes)',
 'def make_mlp(in_dim,hidden,classes):\n    return torch.nn.Sequential(torch.nn.Linear(in_dim,hidden),torch.nn.ReLU(),torch.nn.Linear(hidden,classes))',
 [case('list(make_mlp(3,5,2)(torch.ones(4,3)).shape)',[4,2],label='可配置维度'),case('sum(p.numel() for p in make_mlp(3,5,2).parameters())',32,label='参数注册'),case('sum(isinstance(m,torch.nn.ReLU) for m in make_mlp(2,3,4).modules())',1,label='非线性层'),case('any(isinstance(m,torch.nn.Softmax) for m in make_mlp(2,3,4).modules())',False,label='原始logits')],
 quiz('CrossEntropyLoss 通常接收什么模型输出？',['概率','原始logits','argmax类别编号'],1,['归一化由损失内部处理。','对，保留完整类别得分。','argmax丢掉所需信息。']),
 examples=[example('参数计数','m=torch.nn.Linear(3,2)\nprint(sum(p.numel() for p in m.parameters()))','8','6个权重和2个bias。'),example('单样本','print(list(torch.nn.Linear(4,3)(torch.ones(1,4)).shape))','[1, 3]','单样本也保留batch轴。')],minutes=25)
add('pt17',10,'让 Dataset 管好自己的数据',2,'实现',
 'Dataset描述怎样取一条样本，DataLoader负责组批与打乱。构造时clone输入，返回时再clone样本，能隔离外部修改，避免实验数据被悄悄污染。',
 'x=torch.tensor([[1.,2.],[3.,4.]])\nprint(x[0],len(x))',
 ['继承torch.utils.data.Dataset，先验证x与y首维长度一致。','保存两者clone；__len__返回样本数，__getitem__返回两项的clone。','长度不一致抛ValueError。外部修改原始输入或取出的样本，不应影响数据集。'],
 '定义 FeatureDataset(x,y)，按上述协议与副本规则实现。','class FeatureDataset(torch.utils.data.Dataset)',
 'class FeatureDataset(torch.utils.data.Dataset):\n    def __init__(self,x,y):\n        if len(x)!=len(y):\n            raise ValueError("length mismatch")\n        self.x=x.clone()\n        self.y=y.clone()\n    def __len__(self):\n        return len(self.y)\n    def __getitem__(self,i):\n        return self.x[i].clone(),self.y[i].clone()',
 [case('len(FeatureDataset(torch.ones(3,2),torch.zeros(3)))',3,label='长度'),case('ds[0]',[[1,2],0],setup='x=torch.tensor([[1.,2.]])\nds=FeatureDataset(x,torch.tensor([0]))\nx[0,0]=99\na,b=ds[0]\na[0]=88',label='输入输出隔离'),case('FeatureDataset(torch.ones(2,3),torch.zeros(1))',raises='ValueError',label='长度验证'),case('isinstance(FeatureDataset(torch.ones(1,2),torch.zeros(1)),torch.utils.data.Dataset)',True,label='协议')],
 quiz('组批、打乱数据通常由谁负责？',['Dataset.__getitem__','DataLoader','optimizer'],1,['这里只取一条样本。','对，DataLoader组合取样流程。','优化器更新参数。']),
 examples=[example('独立存储','a=torch.tensor([1.]);b=a.clone()\nb[0]=9\nprint(a.item())','1.0','clone不共享底层存储。'),example('单条样本形状','print(list(torch.ones(4,3)[0].shape))','[3]','取单条样本时没有batch轴。')],minutes=25)
add('pt18',10,'自己实现 collate_fn',2,'实现',
 'collate_fn接收一组样本。等长特征用stack新建batch轴，标签统一转成long。cat连接已有轴，不会自动给你新增batch维。',
 'xs=[torch.ones(3),torch.zeros(3)]\nprint(torch.stack(xs).shape,torch.cat(xs).shape)',
 ['空样本列表抛ValueError。','分别收集特征与标签，特征torch.stack，标签torch.tensor(...,dtype=torch.long)。','单样本仍是[1,D]；返回batch不可与输入特征共享存储。'],
 '定义 collate_samples(samples)，每项是(一维浮点张量,整数标签)，返回(二维特征batch,long标签)。','def collate_samples(samples)',
 'def collate_samples(samples):\n    if not samples:\n        raise ValueError("empty batch")\n    return torch.stack([s[0] for s in samples]),torch.tensor([s[1] for s in samples],dtype=torch.long)',
 [case('collate_samples([(torch.tensor([1.,2.]),0),(torch.tensor([3.,4.]),1)])',[[[1,2],[3,4]],[0,1]],label='组批'),case('[list(v.shape) for v in collate_samples([(torch.ones(3),2)])]',[[1,3],[1]],label='单条样本'),case('str(collate_samples([(torch.ones(2),1)])[1].dtype)','torch.int64',label='标签类型'),case('collate_samples([])',raises='ValueError',label='空输入')],
 quiz('两个[3]向量默认stack后的形状是？',['[6]','[2,3]','[3,2]'],1,['这是cat的结果。','对，新建batch轴。','默认新轴在最前。']),
 examples=[example('stack新增轴','print(list(torch.stack([torch.ones(3)]).shape))','[1, 3]','即使只有一条样本也保留batch轴。'),example('索引标签类型','print(torch.tensor([0,2],dtype=torch.long).dtype)','torch.int64','分类索引通常用long。')],minutes=25)
add('pt19',10,'只训练分类头',2,'实现',
 '迁移学习可冻结backbone、仅更新head。requires_grad控制参数是否求导，优化器参数列表控制哪些参数会更新。eval模式改变某些层的行为，并不自动冻结参数。',
 'm=torch.nn.Linear(2,1)\nm.eval()\nprint(m.weight.requires_grad)',
 ['模型已含backbone和head子模块。','backbone参数requires_grad设False，head全部设True。','返回head参数的list，用于创建优化器；不要用model.eval代替冻结。'],
 '定义 trainable_head(model)，冻结backbone，启用head，返回head全部参数列表。','def trainable_head(model)',
 'def trainable_head(model):\n    for p in model.backbone.parameters():\n        p.requires_grad_(False)\n    for p in model.head.parameters():\n        p.requires_grad_(True)\n    return list(model.head.parameters())',
 [case('all(not p.requires_grad for p in m.backbone.parameters())',True,setup='m=torch.nn.Module()\nm.backbone=torch.nn.Linear(2,3)\nm.head=torch.nn.Linear(3,2)\nout=trainable_head(m)',label='主体冻结'),case('all(p.requires_grad for p in m.head.parameters())',True,setup='m=torch.nn.Module()\nm.backbone=torch.nn.Linear(2,3)\nm.head=torch.nn.Linear(3,2)\nm.head.requires_grad_(False)\nout=trainable_head(m)',label='重新启用head'),case('set(map(id,out))==set(map(id,m.head.parameters()))',True,setup='m=torch.nn.Module()\nm.backbone=torch.nn.Linear(2,3)\nm.head=torch.nn.Linear(3,2)\nout=trainable_head(m)',label='正确参数列表')],
 quiz('model.eval会自动关闭参数梯度吗？',['会','不会','只在CPU上会'],1,['eval和requires_grad是不同开关。','对，必须分别管理。','与设备无关。']),
 examples=[example('eval不冻结','m=torch.nn.Linear(2,1)\nm.eval()\nprint(m.weight.requires_grad)','True','模式和求导状态独立。'),example('显式冻结','p=torch.nn.Parameter(torch.ones(2))\np.requires_grad_(False)\nprint(p.requires_grad)','False','参数需要显式冻结。')],minutes=25)
add('pt20',10,'预测后恢复原来的模式',3,'排错',
 '预测需要eval和no_grad。若预测前模型在训练，结束后应恢复train，否则后续Dropout会悄悄失效。保存原模式并在finally中恢复，也能覆盖前向失败的情况。',
 'm=torch.nn.Dropout(1.0)\nx=torch.ones(2)\nprint(m(x))\nm.eval()\nprint(m(x))',
 ['先保存was_training=model.training，再调用eval。','在with torch.no_grad()中前向并返回输出。','finally内model.train(was_training)，保证原状态恢复。'],
 '定义 predict(model,x)，在eval与no_grad下预测，并恢复原train/eval模式。','def predict(model, x)',
 'def predict(model,x):\n    was_training=model.training\n    model.eval()\n    try:\n        with torch.no_grad():\n            return model(x)\n    finally:\n        model.train(was_training)',
 [case('predict(torch.nn.Dropout(0.9),torch.ones(2,3))',[[1,1,1],[1,1,1]],label='禁用Dropout'),case('out.requires_grad',False,setup='m=torch.nn.Linear(2,1)\nout=predict(m,torch.ones(3,2,requires_grad=True))',label='禁用计算图'),case('m.training',True,setup='m=torch.nn.Linear(2,1)\nm.train()\npredict(m,torch.ones(1,2))',label='恢复train'),case('m.training',False,setup='m=torch.nn.Linear(2,1)\nm.eval()\npredict(m,torch.ones(1,2))',label='保持eval')],
 quiz('eval与no_grad分别负责什么？',['完全相同','层行为与计算图记录','清空梯度与更新参数'],1,['是两个独立开关。','对，通常都需要。','它们不负责这些操作。']),
 bug='def predict(model,x):\n    model.eval()\n    return model(x)',
 examples=[example('层的行为改变','m=torch.nn.Dropout(1.0)\nm.eval()\nprint(m(torch.ones(2)))','tensor([1., 1.])','评估时Dropout保持输入。'),example('关闭梯度记录','x=torch.ones(2,requires_grad=True)\nwith torch.no_grad():\n    y=x*2\nprint(y.requires_grad)','False','输入的requires_grad本身无需改变。')],minutes=30)
